sc_cat_item_producer.script:
/** This script is executed before the Record is generated
* `current`- GlideRecord produced by Record Producer
* Don't use `current.update()` or `current.insert()` as the record is generated by Record Producer
* Don't use `current.setValue('sys_class_name', 'xxx')` as this will trigger reparent flow and can cause data loss
* Avoid `current.setAbortAction()` and generate a separate record
* Use `producer.var1` to access variables
*/
/** This script is executed before the Record is generated */
(function producerScript(producer) {
    function readText(p, name) {
        var v = p[name];
        if (v == null || v === '') return '';
        return String(v);
    }

    function readBool(p, name) {
        var v = p[name];
        if (v == null) return false;
        v = String(v).toLowerCase();
        return (v === 'true' || v === 'on' || v === '1' || v === 'yes');
    }

    // Validation helpers
    function isIPv4(addr) {
        return /^(\d{1,3}\.){3}\d{1,3}$/.test(addr);
    }
    function isIPv6(addr) {
        return /^([a-fA-F0-9:]+:+)+[a-fA-F0-9]+$/.test(addr);
    }
    function isCIDR(addr) {
        return /^(\d{1,3}\.){3}\d{1,3}\/\d{1,2}$/.test(addr) || /^([a-fA-F0-9:]+:+)+[a-fA-F0-9]+\/\d{1,3}$/.test(addr);
    }
    function isFQDN(addr) {
        // FQDN: must have at least one dot, no spaces, no wildcards
        return /^[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)+$/.test(addr);
    }
    function isWildcardFQDN(addr) {
        // Wildcard FQDN: starts with *.
        return /^\*\.[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)+$/.test(addr);
    }
    function isValidAddress(addr) {
        return isIPv4(addr) || isIPv6(addr) || isCIDR(addr) || isFQDN(addr) || isWildcardFQDN(addr);
    }
    function isValidPortList(portStr) {
        if (!portStr) return true;
        var ports = portStr.split(',');
        for (var i = 0; i < ports.length; i++) {
            var port = ports[i].trim();
            if (!/^\d+$/.test(port)) return false;
            var n = parseInt(port, 10);
            if (n < 1 || n > 65535) return false;
        }
        return true;
    }

    // Gather variables
    var payload = {
        privateResourceName: readText(producer, 'private_resource_name'),
        description: readText(producer, 'description'),
        internallyAddress: readText(producer, 'internally_reachable_address'),
        protocol: readText(producer, 'protocol'),
        portRanges: readText(producer, 'port_ranges'),
        resourceGroupType: readText(producer, 'resource_group_type'),
        branchConnections: readBool(producer, 'branch_connections'),
        zeroTrustConnections: readBool(producer, 'zero_trust_connections'),
        vpnConnections: readBool(producer, 'vpn_connections'),
        clientBaseConnection: readBool(producer, 'client_base_connection'),
        changeRemotelyAddress: readBool(producer, 'change_remotely_reachable_address'),
        remotelyReachableAccess: readText(producer, 'remotely_reachable_access')
    };

    // --- VALIDATIONS ---

    // 1. Mandatory fields
    var missing = [];
    if (!payload.privateResourceName) missing.push("Private Resource Name");
    if (!payload.internallyAddress) missing.push("Internally reachable address");
    if (!payload.protocol) missing.push("Protocol");
    if (!payload.resourceGroupType) missing.push("Resource Group Type");
    if (missing.length > 0) {
        gs.addErrorMessage("Missing mandatory fields: " + missing.join(", "));
        producer.redirect = false;
        return;
    }

    // 2. Private Resource Name: only letters, numbers, spaces, hyphens
    if (!/^[A-Za-z0-9\- ]+$/.test(payload.privateResourceName)) {
        gs.addErrorMessage("Resource Name must only contain letters, numbers, spaces, and hyphens.");
        producer.redirect = false;
        return;
    }

    // 3. Internally reachable address: must be FQDN, wildcard FQDN, IPv4, IPv6, or CIDR
    if (!isValidAddress(payload.internallyAddress)) {
        gs.addErrorMessage("Internally reachable address must be a valid FQDN, wildcard FQDN, IPv4, IPv6, or CIDR.");
        producer.redirect = false;
        return;
    }

    // 4. Protocol: must be allowed value
    var allowedProtocols = ["Any", "TCP", "UDP", "HTTP/HTTPS", "SSH", "RDP-TCP"];
    if (allowedProtocols.indexOf(payload.protocol) === -1) {
        gs.addErrorMessage("Invalid protocol selected. Allowed: " + allowedProtocols.join(", "));
        producer.redirect = false;
        return;
    }

    // 5. Port / Ranges: must be numeric, 1-65535, comma-separated
    if (payload.portRanges && !isValidPortList(payload.portRanges)) {
        gs.addErrorMessage("Port(s) must be numbers between 1 and 65535.");
        producer.redirect = false;
        return;
    }

    // 6. Remotely Reachable Access: if Client Base Connection, must be valid address
    if (payload.clientBaseConnection && payload.remotelyReachableAccess && !isValidAddress(payload.remotelyReachableAccess)) {
        gs.addErrorMessage("Remotely Reachable Access must be a valid FQDN, wildcard FQDN, IPv4, IPv6, or CIDR.");
        producer.redirect = false;
        return;
    }

    // 7. Protocol-specific address validation
    if (payload.protocol === "TCP" || payload.protocol === "HTTP/HTTPS") {
        // Only IPv4 or IPv6 allowed for internally reachable address
        if (!(isIPv4(payload.internallyAddress) || isIPv6(payload.internallyAddress))) {
            gs.addErrorMessage("For TCP or HTTP/HTTPS protocol, Internally reachable address must be IPv4 or IPv6.");
            producer.redirect = false;
            return;
        }
    }

    // --- END VALIDATIONS ---

    gs.info("[Producer] Payload JSON: " + JSON.stringify(payload));

    //  Call Script Include
    var si = new global.CiscoSecureAccessCreatePrivateResource();
    var result = si.createPrivateResource(payload);

    //  Log result from Script Include
    gs.info("[Producer] Script Include returned: " + JSON.stringify(result));

})(producer);
